<?php
namespace Tests\Feature;
use App\Models\Person;use App\Models\User;use App\Models\Visit;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\DB;use Tests\TestCase;
class CompletionFeaturesTest extends TestCase {
 use RefreshDatabase;
 private function token(string $role):string{$u=User::create(['username'=>$role.uniqid(),'name'=>$role,'role'=>$role,'status'=>'active','password'=>'password']);$t=$role.'-'.uniqid();DB::table('api_tokens')->insert(['user_id'=>$u->id,'token_hash'=>hash('sha256',$t),'created_at'=>now(),'updated_at'=>now()]);return $t;}
 public function test_admin_staff_and_clinical_access_controls():void{$admin=$this->token('admin');$lab=$this->token('lab');$this->withToken($admin)->postJson('/api/admin/staff',['name'=>'New Dentist','username'=>'dentist2','role'=>'dental','password'=>'secret1'])->assertCreated();$this->withToken($lab)->getJson('/api/patients')->assertForbidden();$this->assertDatabaseHas('audit_logs',['action'=>'created','entity_type'=>'user']);}
 public function test_seeded_pharmacy_and_dental_accounts_can_login():void{$this->seed();$this->postJson('/api/auth/login',['username'=>'pharmacist','password'=>'password'])->assertOk()->assertJsonPath('data.user.role','pharmacy');$this->postJson('/api/auth/login',['username'=>'dental','password'=>'password'])->assertOk()->assertJsonPath('data.user.role','dental');}
 public function test_seeded_records_account_can_access_records_only():void{$this->seed();$login=$this->postJson('/api/auth/login',['username'=>'records','password'=>'password'])->assertOk()->assertJsonPath('data.user.role','records')->json('data');$this->withToken($login['token'])->getJson('/api/records/drugs')->assertOk();$this->withToken($login['token'])->getJson('/api/admin/staff')->assertForbidden();}
 public function test_patient_academic_details_determine_card_expiry_year():void{$p=Person::create(['person_type'=>'student','first_name'=>'Aisha','last_name'=>'Nakato','student_number'=>'2400000099','medical_card_number'=>'MC-1']);$u=User::create(['person_id'=>$p->id,'username'=>'2400000099','name'=>'Aisha','role'=>'student','status'=>'active','password'=>'password']);$t='patient-token';DB::table('api_tokens')->insert(['user_id'=>$u->id,'token_hash'=>hash('sha256',$t),'created_at'=>now(),'updated_at'=>now()]);$this->withToken($t)->getJson('/api/my/profile')->assertOk()->assertJsonPath('data.year_of_entry',2024);$this->withToken($t)->putJson('/api/my/profile',['year_of_entry'=>2024,'year_of_study'=>3,'course_duration'=>4])->assertOk()->assertJsonPath('data.medical_card_expiry','2028-12-31');}
 public function test_partial_dispensing_dental_and_pdf_report():void{$doctor=$this->token('doctor');$pharmacy=$this->token('pharmacy');$dental=$this->token('dental');$admin=$this->token('admin');$p=Person::create(['person_type'=>'student','first_name'=>'Test','last_name'=>'Patient']);$v=Visit::create(['visit_number'=>'V-COMPLETE','queue_number'=>'Q1','person_id'=>$p->id]);$drug=DB::table('drugs')->insertGetId(['name'=>'Test Drug','stock_qty'=>10,'created_at'=>now(),'updated_at'=>now()]);$this->withToken($doctor)->postJson("/api/visits/$v->id/consultation",['diagnosis'=>'Dental infection','routes'=>['sent_to_pharmacy','sent_to_dental'],'prescriptions'=>[['drug_id'=>$drug,'quantity'=>5]]])->assertOk();$rx=DB::table('prescriptions')->value('id');$item=DB::table('prescription_items')->value('id');$this->withToken($pharmacy)->putJson("/api/prescriptions/$rx/dispense",['items'=>[['item_id'=>$item,'quantity'=>2]]])->assertOk()->assertJsonPath('data.status','partial');$ref=DB::table('referrals')->value('id');$this->withToken($dental)->putJson("/api/referrals/$ref/complete",['outcome'=>'Extraction completed'])->assertOk();$this->assertDatabaseHas('drugs',['id'=>$drug,'stock_qty'=>8]);$pdf=$this->withToken($admin)->get('/api/records/export?from=2026-01-01&to=2026-12-31')->assertOk()->assertHeader('content-type','application/pdf');$this->assertStringStartsWith('%PDF-1.4',$pdf->getContent());}
}
